320	        private void UpdateBindingPrompts()
321	        {
322	            _showGamepadPrompts = HumanInputActions.LastUsedGamepad && Gamepad.current != null;
323	            _seenBindingRevision = HumanInputActions.BindingRevision;
324	            _moveDeck.EnableInClassList("controller-prompts", _showGamepadPrompts);
325	            string group = _showGamepadPrompts ? HumanInputActions.GamepadGroup : HumanInputActions.KeyboardGroup;
326	
327	            for (int i = 0; i < _abilitySlots.Length; i++)
328	            {
329	                var slot = _abilitySlots[i];
330	                string action = _showGamepadPrompts
331	                    ? AbilitySlotDefs[i].Action switch
332	                    {
333	                        "SlotA" => "Slot1",
334	                        "SlotE" => "Slot3",
335	                        "SlotR" => "Slot2",
336	                        "SlotF" => "Slot4",
337	                        _ => AbilitySlotDefs[i].Action,
338	                    }
339	                    : AbilitySlotDefs[i].Action;
340	                string path = BindingPath(action, group);
341	                var buttonGlyph = default(InputPromptAtlas.Glyph);
342	                bool hasButton = _showGamepadPrompts &&
343	                    (_promptAtlas ??= new InputPromptAtlas()).TryXbox(path, out buttonGlyph);
344	                slot.Button.style.display = hasButton ? DisplayStyle.Flex : DisplayStyle.None;
345	                slot.Key.style.display = hasButton ? DisplayStyle.None : DisplayStyle.Flex;
346	                if (hasButton)
347	                    SetPromptImage(slot.Button, buttonGlyph);
348	                else
349	                {
350	                    string label = HumanInputActions.BindingLabel(action, group);
351	                    slot.Key.text = _showGamepadPrompts
352	                        ? label : InputPromptAtlas.KeyboardDisplayLabel(path, label);
353	                }
354	            }
355	
356	            string modifierPath = BindingPath("SpecialModifier", HumanInputActions.GamepadGroup);
357	            string shoulderLabel = modifierPath?.EndsWith("/leftShoulder", StringComparison.OrdinalIgnoreCase) == true
358	                ? "LB" : modifierPath?.EndsWith("/rightShoulder", StringComparison.OrdinalIgnoreCase) == true
359	                    ? "RB" : null;
360	            var modifierGlyph = default(InputPromptAtlas.Glyph);
361	            bool hasModifier = _showGamepadPrompts &&
362	                (_promptAtlas ??= new InputPromptAtlas()).TryXbox(modifierPath, out modifierGlyph);
363	            bool showModifierGlyph = hasModifier && shoulderLabel == null;
364	            _modifierButton.style.display = showModifierGlyph ? DisplayStyle.Flex : DisplayStyle.None;
365	            _modifierKey.style.display = showModifierGlyph ? DisplayStyle.None : DisplayStyle.Flex;
366	            _modifierKey.text = _showGamepadPrompts
367	                ? shoulderLabel ?? HumanInputActions.BindingLabel("SpecialModifier", HumanInputActions.GamepadGroup)
368	                : "SPECIALS";
369	            if (hasModifier) SetPromptImage(_modifierButton, modifierGlyph);
370	            _modifierPrompt.EnableInClassList("keyboard-modifier", !_showGamepadPrompts);
371	        }
