490	        /// <summary>
491	        /// Provide the character definition: resolves ability icons, per-slot max
492	        /// cooldowns (max of grounded/airborne), and the locked (no-data) state.
493	        /// </summary>
494	        public void SetCharacterDefinition(CharacterDefinition def)
495	        {
496	            _charDef = def;
497	            if (_moveTooltip != null) _moveTooltip.style.display = DisplayStyle.None;
498	            bool isGrounded = _getState == null || _localEntityId == 0 || _getState(_localEntityId).IsGrounded;
499	
500	            if (_abilitySlots == null || _abilitySlots.Length == 0) return;
501	            for (int i = 0; i < _abilitySlots.Length; i++)
502	            {
503	                var slot = _abilitySlots[i];
504	                var d = AbilitySlotDefs[i];
505	                var grounded = def.GetSlotAbility(d.SlotIndex, airborne: false);
506	                var airborne = def.GetSlotAbility(d.SlotIndex, airborne: true);
507	
508	                ushort max = 0;
509	                if (grounded != null) max = grounded.CooldownTicks;
510	                if (airborne != null && airborne.CooldownTicks > max) max = airborne.CooldownTicks;
511	                slot.MaxCooldown = max;
512	                slot.Locked = grounded == null && airborne == null;
513	                slot.Root.EnableInClassList("locked", slot.Locked);
514	
515	                bool normal = i < 4;
516	                slot.GroundAvailable = grounded != null;
517	                slot.AirAvailable = airborne != null;
518	                // The HUD is a stable control legend, even when the active move is aerial.
519	                var displayAbility = grounded ?? airborne;
520	                slot.DisplayName = MoveLabel(displayAbility);
521	                slot.Artwork = LoadSlotIcon(displayAbility, normal);
522	                SetSlotPresentation(slot, isGrounded);
523	            }
524	
525	        }
