531	        private SlotArtwork LoadSlotIcon(AbilitySpec spec, bool normal)
532	        {
533	            if (spec == null || string.IsNullOrEmpty(spec.IconName)) return default;
534	            string path = $"Icons/{_charDef.Class}/";
535	            string cardPath = $"UI/AbilityCards/{_charDef.Class}/";
536	            var tint = normal ? MoveInk : Color.white;
537	            var cardIcons = Resources.LoadAll<Sprite>(cardPath + spec.IconName);
538	            if (cardIcons.Length > 0) return new SlotArtwork(null, cardIcons[0], Color.white);
539	            return new SlotArtwork(Resources.Load<Texture2D>(path + spec.IconName), null, tint);
540	        }
