621	        /// <summary>
622	        /// Refresh all HUD data from the simulation. Called by the owning MatchBase
623	        /// each fixed tick. The player cards are updated from simulation state.
624	        /// </summary>
625	        public void Refresh()
626	        {
627	            if (_getState == null || _uiDocument == null) return;
628	
629	            foreach (var kv in _billboardPanels)
630	                UpdatePanel(kv.Value, _getState(kv.Key));
631	            // Paired move deck — local player only; no ground/air selector.
632	            if (_localEntityId != 0)
633	            {
634	                var state = _getState(_localEntityId);
635	
636	
637	                for (int i = 0; i < _abilitySlots.Length; i++)
638	                {
639	                    var slot = _abilitySlots[i];
640	                    SetSlotPresentation(slot, state.IsGrounded);
641	                    if (slot.Locked) continue;
642	                    UpdateCooldownSlot(slot, state.GetCooldown((byte)(AbilitySlotDefs[i].SlotIndex + 1)));
643	                }
644	
645	                // Accepted activations drive feedback, including consecutive
646	                // activations of the same slot.
647	                byte castSlot = state.AttackSlot;
648	                if (castSlot != _prevAttackSlot || state.AttackSequence != _prevAttackSequence)
649	                {
650	                    if (castSlot != 0)
651	                    {
652	                        for (int i = 0; i < _abilitySlots.Length; i++)
653	                        {
654	                            if (AbilitySlotDefs[i].SlotIndex + 1 == castSlot)
655	                            {
656	                                PulseConsumed(_abilitySlots[i]);
657	                                break;
658	                            }
659	                        }
660	                    }
661	                    _prevAttackSlot = castSlot;
662	                    _prevAttackSequence = state.AttackSequence;
663	                }
664	            }
665	        }
