667	        /// <summary>Quick shrink-and-spring pulse — visual "spent" feedback for a used action.</summary>
668	        private void PulseConsumed(ActionSlot s)
669	        {
670	            s.PulseTimer = 0f;
671	            s.Root.RemoveFromClassList("ready-pulse");
672	            s.UsedTimer = JuiceDuration;
673	            s.Root.EnableInClassList("used-pulse", true);
674	        }
