676	        private void UpdateCooldownSlot(ActionSlot s, ushort cooldown)
677	        {
678	            bool onCooldown = cooldown > 0;
679	
680	            s.Cooldown.style.display = onCooldown ? DisplayStyle.Flex : DisplayStyle.None;
681	            s.Timer.style.display = onCooldown ? DisplayStyle.Flex : DisplayStyle.None;
682	            s.Root.EnableInClassList("on-cooldown", onCooldown);
683	            if (onCooldown)
684	            {
685	                float frac = s.MaxCooldown > 0 ? Mathf.Clamp01(cooldown / (float)s.MaxCooldown) : 1f;
686	                s.Cooldown.style.scale = new Scale(new Vector2(frac, 1f));
687	                s.Timer.text = $"{(cooldown / 60f):0.0}s";
688	            }
689	            else
690	            {
691	                s.Timer.text = "";
692	            }
693	
694	            // One short readiness stamp; no repeated pulse or white icon flash.
695	            if (s.PrevCooldown > 0 && cooldown == 0)
696	            {
697	                s.PulseTimer = ReadyDuration;
698	                s.Root.EnableInClassList("ready-pulse", true);
699	            }
700	            else if (onCooldown)
701	            {
702	                s.PulseTimer = 0f;
703	                s.Root.RemoveFromClassList("ready-pulse");
704	            }
705	            // NOTE: no "consumed" pulse here — cooldown only moves at ability END, not
706	            // press, so this would fire ~1 move later. Press feedback is driven from the
707	            // AttackSlot transition in Refresh (see PulseConsumed).
708	            s.PrevCooldown = cooldown;
709	        }
