713	        private void Update()
714	        {
715	            float dt = Time.unscaledDeltaTime;
716	            if (_abilitySlots.Length > 0 &&
717	                (_seenBindingRevision != HumanInputActions.BindingRevision ||
718	                 _showGamepadPrompts != (HumanInputActions.LastUsedGamepad && Gamepad.current != null)))
719	                UpdateBindingPrompts();
720	            UpdateNetworkStats();
721	            UpdateModifierFeedback();
722	            FitMoveDeck();
723	
724	            for (int i = 0; i < _abilitySlots.Length; i++) TickSlotJuice(_abilitySlots[i], dt);
725	
726	            foreach (var panel in _billboardPanels.Values)
727	                TickPanelJuice(panel, dt);
728	        }
