730	        private void UpdateModifierFeedback()
731	        {
732	            if (_moveDeck == null) return;
733	            bool held = _showGamepadPrompts && HumanInputActions.Get("SpecialModifier").IsPressed() &&
734	                !ChatInputGate.SuppressGameplay && !HumanInputActions.IsCapturing &&
735	                !(SettingsOverlay.Active is { IsOpen: true }) &&
736	                !(MatchPauseMenu.Active is { IsPaused: true });
737	            if (held == _modifierHeld) return;
738	            _modifierHeld = held;
739	            _moveDeck.EnableInClassList("modifier-held", held);
740	        }
