742	        private void FitMoveDeck()
743	        {
744	            if (_moveDeck == null || _movePairs == null || _moveDeck.panel == null) return;
745	            float width = _moveDeck.resolvedStyle.width;
746	            if (float.IsNaN(width) || width <= 0f) return;
747	            const float preferredWidth = 576f;
748	            bool rightAligned = _billboardLayer != null && _billboardLayer.childCount > 0 &&
749	                _moveDeck.worldBound.yMin < _billboardLayer.worldBound.yMax + 20f &&
750	                (width - preferredWidth) * 0.5f < _billboardLayer.worldBound.xMax + 20f;
751	            float availableWidth = rightAligned
752	                ? width - _billboardLayer.worldBound.xMax - 38f
753	                : width - 96f;
754	            float scale = Mathf.Clamp(availableWidth / preferredWidth, 0.5f, 1f);
755	            if (rightAligned != _moveDeckRightAligned)
756	            {
757	                _moveDeckRightAligned = rightAligned;
758	                _moveDeck.style.justifyContent = rightAligned ? Justify.FlexEnd : Justify.Center;
759	                _moveDeck.style.paddingRight = rightAligned ? 18f : 0f;
760	            }
761	            if (Mathf.Abs(scale - _moveDeckScale) > 0.001f)
762	            {
763	                _moveDeckScale = scale;
764	                _movePairs.style.scale = new Scale(Vector2.one * scale);
765	            }
766	        }
