768	        private static void DrawMoveTicket(MeshGenerationContext context)
769	        {
770	            float width = context.visualElement.contentRect.width;
771	            float height = context.visualElement.contentRect.height;
772	            float seam = height * 0.5f;
773	            var painter = context.painter2D;
774	            painter.lineWidth = 2f;
775	            painter.strokeColor = MoveInk;
776	            painter.fillColor = MovePaper;
777	            painter.BeginPath();
778	            painter.MoveTo(new Vector2(16, 2));
779	            painter.LineTo(new Vector2(width - 2, 2));
780	            painter.LineTo(new Vector2(width - 14, seam - 16));
781	            painter.LineTo(new Vector2(width - 2, seam));
782	            painter.LineTo(new Vector2(2, seam));
783	            painter.LineTo(new Vector2(2, seam - 16));
784	            painter.ClosePath();
785	            painter.Fill();
786	            painter.Stroke();
787	
788	            painter.fillColor = MoveInk;
789	            painter.BeginPath();
790	            painter.MoveTo(new Vector2(2, seam));
791	            painter.LineTo(new Vector2(width - 2, seam));
792	            painter.LineTo(new Vector2(width - 14, height - 18));
793	            painter.LineTo(new Vector2(width - 28, height - 2));
794	            painter.LineTo(new Vector2(16, height - 2));
795	            painter.LineTo(new Vector2(2, height - 18));
796	            painter.ClosePath();
797	            painter.Fill();
798	            painter.Stroke();
799	
800	            painter.lineWidth = 6f;
801	            painter.strokeColor = MoveOrange;
802	            painter.BeginPath();
803	            painter.MoveTo(new Vector2(16, 4));
804	            painter.LineTo(new Vector2(width - 3, 4));
805	            painter.Stroke();
806	        }
