808	        private void UpdateNetworkStats()
809	        {
810	            if (_networkStatsLabel == null) return;
811	            int mode = ClientSettingsService.Instance.NetworkStats;
812	            _networkStatsLabel.style.display = mode == 0 ? DisplayStyle.None : DisplayStyle.Flex;
813	            if (mode == 0) return;
814	            if (_networkClient == null)
815	            {
816	                _networkStatsLabel.text = "NETWORK: OFFLINE";
817	                return;
818	            }
819	            if (!_networkClient.IsServerConnected)
820	            {
821	                _networkStatsLabel.text = "NETWORK: DISCONNECTED";
822	                return;
823	            }
824	            float? ping = _networkClient.LastPingMilliseconds;
825	            _networkStatsLabel.text = !ping.HasValue
826	                ? "PING: MEASURING…"
827	                : mode == 1
828	                    ? $"PING: {ping.Value:F0} ms"
829	                    : $"PING: {ping.Value:F0} ms\nSERVER: {_networkClient.ServerEndpoint}\nTICK: {_networkClient.LastPingServerTick}";
830	        }
