832	        private static void TickPanelJuice(OverheadPanel panel, float dt)
833	        {
834	            bool flashing = panel.HitFlashTimer > 0f && !ClientSettingsService.Instance.ReducedFlashing;
835	            if (panel.HitFlashTimer > 0f) panel.HitFlashTimer -= dt;
836	            panel.Damage.style.color = flashing ? Color.white : panel.TierColor;
837	            panel.Damage.EnableInClassList("damage-hit", flashing);
838	
839	            if (panel.StockToastTimer > 0f)
840	            {
841	                panel.StockToastTimer -= dt;
842	                float elapsed = panel.StockToastDuration - panel.StockToastTimer;
843	                float scale = elapsed < 0.1f ? Mathf.Lerp(0.88f, 1.04f, elapsed / 0.1f)
844	                    : elapsed < 0.18f ? Mathf.Lerp(1.04f, 1f, (elapsed - 0.1f) / 0.08f) : 1f;
845	                panel.StockToast.style.scale = new Scale(Vector2.one *
846	                    (ClientSettingsService.Instance.ReducedFlashing ? 1f : scale));
847	                panel.StockToast.style.opacity = Mathf.Clamp01(panel.StockToastTimer / 0.18f);
848	                if (panel.StockToastTimer <= 0f)
849	                {
850	                    panel.StockToast.style.opacity = 0f;
851	                    panel.StockToast.style.display = DisplayStyle.None;
852	                }
853	            }
854	        }
