856	        private static void TickSlotJuice(ActionSlot s, float dt)
857	        {
858	            s.Root.EnableInClassList("quiet-feedback", ClientSettingsService.Instance.ReducedFlashing);
859	            if (s.PulseTimer > 0f)
860	            {
861	                s.PulseTimer -= dt;
862	                s.Root.EnableInClassList("ready-pulse", s.PulseTimer > 0f);
863	            }
864	            if (s.UsedTimer > 0f)
865	            {
866	                s.UsedTimer -= dt;
867	                s.Root.EnableInClassList("used-pulse", s.UsedTimer > 0f);
868	            }
869	        }
